        "Project Description"
      ],
      "name changes": []
    },
    "Project Execution": {
      "derived from": "Project Execution Subdomain",
      "objects": [
        "Contact",
        "Completed Work",
        "Feedback",
        "Payment"
      ],
      "name changes": []
    },
    "Administration": {
      "derived from": "Administration Subdomain",
      "objects": [
        "Platform Manager",
        "Verification",
        "Platform Guidelines",
        "Dispute Report"
      ],
      "name changes": []
    }
  }
}
```
